(7664077, 1249955, 39144, '<td valign="top">I really like the colors in this one. Nice work!</td>', 'I really like the colors in this one. Nice work!', '2020-05-27 01:55:10.000000', NULL, 1),
(7664078, 1250027, 39144, '<td valign="top">Tulips are amazing. Love the shallow DOF in this shot.</td>', 'Tulips are amazing. Love the shallow DOF in this shot.', '2020-05-27 01:55:43.000000', NULL, 1),
(7664080, 1249744, 39144, '<td valign="top">I love this time of year with all of the baby animals. I couldnt get any to cooperate with me, but this shot is fantastic.</td>', 'I love this time of year with all of the baby animals. I couldnt get any to cooperate with me, but this shot is fantastic.', '2020-05-27 01:57:44.000000', NULL, 1),
