(7664085, 1249407, 39144, '<td valign="top">I have never seen a flower like this. I love it!</td>', 'I have never seen a flower like this. I love it!', '2020-05-27 02:01:26.000000', NULL, 1),
(7664102, 1250028, 114285, '<td valign="top">Oh what a pretty bee, the stripes ;)</td>', 'Oh what a pretty bee, the stripes ;)', '2020-05-27 03:54:10.000000', NULL, 1),
(7664106, 1250059, 4008, '<td valign="top">Feels like an autumn bouquet as result of the processing, but I guess this was your intention considering the title</td>', 'Feels like an autumn bouquet as result of the processing, but I guess this was your intention considering the title', '2020-05-27 04:13:54.000000', NULL, 1),
(7664107, 1250035, 4008, '<td valign="top">What is the man doing? Why is he in the picture?</td>', 'What is the man doing? Why is he in the picture?', '2020-05-27 04:15:21.000000', NULL, 1),
(7664115, 1249918, 34082, '<td valign="top">I would have preferred more focus on the bird and a view without the dead branch on the right. Nice shot.</td>', 'I would have preferred more focus on the bird and a view without the dead branch on the right. Nice shot.', '2020-05-27 06:52:47.000000', NULL, 1),
(7664153, 1249824, 100831, '<td valign="top">Nice angle. Good sky.</td>', 'Nice angle. Good sky.', '2020-05-27 12:33:42.000000', NULL, 1),
(7664154, 1250019, 65234, '<td valign="top">Soft and dreamy with a tack sharp bug. LOVE the composition and the light.</td>', 'Soft and dreamy with a tack sharp bug. LOVE the composition and the light.', '2020-05-27 12:55:25.000000', NULL, 1),
(7664156, 1250062, 65234, '<td valign="top">Literally said "wow" out loud when I opened this. Love everything about it: the light, the color, the composition, and that glorious bokeh. It''s just magical.</td>', 'Literally said "wow" out loud when I opened this. Love everything about it: the light, the color, the composition, and that glorious bokeh. It''s just magical.', '2020-05-27 12:56:54.000000', NULL, 1),
(7664158, 1250034, 65234, '<td valign="top">Gorgeous light and composition and that bug is tack sharp (and I''m guessing rather small). So very well done.</td>', 'Gorgeous light and composition and that bug is tack sharp (and I''m guessing rather small). So very well done.', '2020-05-27 12:58:08.000000', NULL, 1),
(7664160, 1249656, 65234, '<td valign="top">Youngsters are surely a sign of the season. Very cute and nicely captured.</td>', 'Youngsters are surely a sign of the season. Very cute and nicely captured.', '2020-05-27 12:59:39.000000', NULL, 1),
(7664162, 1249999, 65234, '<td valign="top">Great macro! I can see the little hairs on the bee. If that pollen sac were in focus this would be absolutely perfect to me, but man, it''s an excellent capture as is.</td>', 'Great macro! I can see the little hairs on the bee. If that pollen sac were in focus this would be absolutely perfect to me, but man, it''s an excellent capture as is.', '2020-05-27 13:01:07.000000', NULL, 1),
(7664168, 1250069, 65234, '<td valign="top">Beautiful scene with nice detail throughout. Very serene.</td>', 'Beautiful scene with nice detail throughout. Very serene.', '2020-05-27 13:06:47.000000', NULL, 1),
(7664170, 1250061, 65234, '<td valign="top">Great capture and title! Would like to see a hint of junior''s eyeballs; on my screen the baby''s face is pure black.</td>', 'Great capture and title! Would like to see a hint of junior''s eyeballs; on my screen the baby''s face is pure black.', '2020-05-27 13:08:46.000000', NULL, 1),
(7664172, 1250017, 65234, '<td valign="top">Love the pinks and purples.</td>', 'Love the pinks and purples.', '2020-05-27 13:09:12.000000', NULL, 1),
(7664174, 1250013, 65234, '<td valign="top">Great DOF here and the flowers are very interesting to me.</td>', 'Great DOF here and the flowers are very interesting to me.', '2020-05-27 13:10:12.000000', NULL, 1),
(7664176, 1249408, 65234, '<td valign="top">Perfect title. These guys are simply adorable and certainly something I expect to see in springtime.</td>', 'Perfect title. These guys are simply adorable and certainly something I expect to see in springtime.', '2020-05-27 13:11:03.000000', NULL, 1),
(7664178, 1250028, 65234, '<td valign="top">A striped eye; very cool! Nice, nice macro. I might have composed a little more off-center, but that''s a personal preference. With that slight angle to the flower the composition just feels off-balance to me.</td>', 'A striped eye; very cool! Nice, nice macro. I might have composed a little more off-center, but that''s a personal preference. With that slight angle to the flower the composition just feels off-balance to me.', '2020-05-27 13:15:56.000000', NULL, 1),
(7664179, 1250054, 65234, '<td valign="top">Beautiful butterfly and I like the composition. I wish the light was a little less flat.</td>', 'Beautiful butterfly and I like the composition. I wish the light was a little less flat.', '2020-05-27 13:16:38.000000', NULL, 1),
(7664180, 1249721, 65234, '<td valign="top">Well, that''s different! I like the old-timey feel to this.</td>', 'Well, that''s different! I like the old-timey feel to this.', '2020-05-27 13:17:10.000000', NULL, 1),
(7664182, 1249862, 65234, '<td valign="top">Nice capture. I''d like to see a little more of the wings, but I know it''s really tough to capture a little insect in flight.</td>', 'Nice capture. I''d like to see a little more of the wings, but I know it''s really tough to capture a little insect in flight.', '2020-05-27 13:18:44.000000', NULL, 1),
(7664184, 1249891, 65234, '<td valign="top">Nicely and dramatically lit.</td>', 'Nicely and dramatically lit.', '2020-05-27 13:19:17.000000', NULL, 1),
(7664185, 1250060, 65234, '<td valign="top">Feels like early morning.</td>', 'Feels like early morning.', '2020-05-27 13:21:06.000000', NULL, 1),
(7664186, 1250052, 65234, '<td valign="top">Pretty, soft light and color. Love the veining on the petals.</td>', 'Pretty, soft light and color. Love the veining on the petals.', '2020-05-27 13:22:23.000000', NULL, 1),
(7664187, 1249479, 65234, '<td valign="top">When this first opened (I''m on a slow connection) it was all trees, so I was very pleasantly surprised to see the bluebells. Adds SO much to the scene. Very rich greens here; feels very much like Spring.</td>', 'When this first opened (I''m on a slow connection) it was all trees, so I was very pleasantly surprised to see the bluebells. Adds SO much to the scene. Very rich greens here; feels very much like Spring.', '2020-05-27 13:23:53.000000', NULL, 1),
(7664188, 1249454, 65234, '<td valign="top">What a capture! I would love to see something like this in person. Nit: feathers on top of the head look oversharpened to me.</td>', 'What a capture! I would love to see something like this in person. Nit: feathers on top of the head look oversharpened to me.', '2020-05-27 13:25:05.000000', NULL, 1),
(7664189, 1250068, 65234, '<td valign="top">That head and eye stand out beautifully; can''t help but want the rest of the closer leg in focus, too. Personal peccadillo. I do love those antennae, though.</td>', 'That head and eye stand out beautifully; can''t help but want the rest of the closer leg in focus, too. Personal peccadillo. I do love those antennae, though.', '2020-05-27 13:28:22.000000', NULL, 1),
(7664190, 1250003, 65234, '<td valign="top">Nice light and interesting pose. Not sure what I think of the processing...it''s very swirly.</td>', 'Nice light and interesting pose. Not sure what I think of the processing...it''s very swirly.', '2020-05-27 13:29:43.000000', NULL, 1),
(7664191, 1249918, 65234, '<td valign="top">Pretty bird and flowers. The image is a little busy to me; I''d have cropped much tighter to get the bird''s head more on a rule of thirds composition. Maybe cloned out a few extraneous bare branches. I''d also lighten the shadows so they weren''t so harsh and contrasty. JMO.</td>', 'Pretty bird and flowers. The image is a little busy to me; I''d have cropped much tighter to get the bird''s head more on a rule of thirds composition. Maybe cloned out a few extraneous bare branches. I''d also lighten the shadows so they weren''t so harsh and contrasty. JMO.', '2020-05-27 13:39:38.000000', NULL, 1),
(7664193, 1249951, 65234, '<td valign="top">Muscovy duck? Mama is way cool. Sort of want all the kids in focus.</td>', 'Muscovy duck? Mama is way cool. Sort of want all the kids in focus.', '2020-05-27 13:40:45.000000', NULL, 1),
(7664194, 1249667, 65234, '<td valign="top">I like the flower, but I have to ask: why the blue leaves? They don''t make the image more Spring-like to my eye.</td>', 'I like the flower, but I have to ask: why the blue leaves? They don''t make the image more Spring-like to my eye.', '2020-05-27 13:43:28.000000', NULL, 1),
